let lifetime = 50;

export class Renderer extends RendererCanvas {
    live: boolean = false;
    m: number[] = [0, 0]
    // walls: Wall[] = [];
    // sun: Sun;
    t: number = 0.0;
    // lifetime;
    lifecycle;
    recordTime: number;
    target;
    population: Population;
    obstacles
    constructor(div: any) {
        super(div);
        this.canvas.style.position = 'relative';
        this.canvas.style.width = '100%';
        this.canvas.style.height = '100%';


        // this.lifetime = 1000;

        // Initialize variables
        this.lifecycle = 0;
        this.recordTime = lifetime;

        this.target = new Obstacle(this.canvas.width / 2 - 12, 24, 24, 24);

        // Create a population with a mutation rate, and population max
        let mutationRate = 0.01;
        this.population = new Population(this.target, mutationRate, 100);

        // Create the obstacle course
        this.obstacles = [];
        // this.obstacles.push(new Obstacle(100, 300, 500, 10));
        this.obstacles.push(new Obstacle(this.canvas.width / 2 - 100, this.canvas.height / 2, 200, 10));



        this.start();
    }
    public mouseClick(x: number, y: number): void {
        
    }
    public mouseMove(x: number, y: number): void {
        // this.sun.updateDirection(x, y);
        this.m[0] = x;
        this.m[1] = y;
    }
    public render(ctx: CanvasRenderingContext2D): void {
        this.t += 0.01;
        this.update(ctx);

        // this.walls.forEach((w) => { w.draw(ctx); });
        // this.sun.draw(ctx, this.t);
    }
    public update(ctx: CanvasRenderingContext2D) {

        // Draw the start and target positions


        // If the generation hasn't ended yet
        if (this.lifecycle < lifetime) {
            this.population.live(this.obstacles, ctx);
            if (this.population.targetReached() && this.lifecycle < this.recordTime) {
                this.recordTime = this.lifecycle;
            }
            this.lifecycle++;
            // Otherwise a new generation
        } else {
            this.lifecycle = 0;
            this.population.calcFitness();
            this.population.selection();
            this.population.reproduction();
        }



        // Draw the obstacles
        // console.log()
        for (let i = 0; i < this.obstacles.length; i++) {
            this.obstacles[i].display(ctx);
        }

        // Display some info

        // fill(0);
        // noStroke();
        // text("Generation #: " + this.population.getGenerations(), 10, 18);
        // text("Cycles left: " + (this.lifetime - this.lifecycle), 10, 36);
        // text("Record cycles: " + this.recordtime, 10, 54);


        // console.log(ctx)

        ctx.beginPath();
        ctx.arc(this.m[0], this.m[1], 10, 0, Math.PI * 2)
        ctx.closePath();
        ctx.fill()

        this.target.display(ctx);
    }
}





