// Rocket class -- this is just like our Boid / Particle class
// the only difference is that it has DNA & fitness

class Rocket {
    acceleration
    velocity: Vector3
    position: Vector3
    r
    dna
    finishTime
    recordDist
    fitness
    geneCounter
    hitObstacle
    hitTarget

    target

    ctx: CanvasRenderingContext2D;

    constructor(pos: Vector3, target: any, dna: any, totalRockets: any) {
        this.target = target;
        // console.log(pos)
        // All of our physics stuff
        this.acceleration = new Vector3(0, 0, 0);
        this.velocity = new Vector3(0, 0, 0);
        this.position = deepCopy(pos)
        this.r = 4;
        this.dna = dna;
        this.finishTime = 0; // We're going to count how long it takes to reach target
        this.recordDist = 10000; // Some high number that will be beat instantly

        this.fitness = 0;
        this.geneCounter = 0;
        this.hitObstacle = false; // Am I stuck on an obstacle?
        this.hitTarget = false; // Did I reach the target
    }

    // FITNESS FUNCTION
    // distance = distance from target
    // finish = what order did i finish (first, second, etc. . .)
    // f(distance,finish) =   (1.0f / finish^1.5) * (1.0f / distance^6);
    // a lower finish is rewarded (exponentially) and/or shorter distance to target (exponetially)
    public calcFitness() {
        if (this.recordDist < 1) this.recordDist = 1;

        // Reward finishing faster and getting close
        this.fitness = 1 / (this.finishTime * this.recordDist);

        // Make the function exponential
        this.fitness = Math.pow(this.fitness, 4);

        if (this.hitObstacle) this.fitness *= 0.1; // lose 90% of fitness hitting an obstacle
        if (this.hitTarget) this.fitness *= 2; // twice the fitness for finishing!
    }

    // Run in relation to all the obstacles
    // If I'm stuck, don't bother updating or checking for intersection
    public run(os: any, ctx: CanvasRenderingContext2D) {


        if ((0 > this.position.x) ||
        (ctx.canvas.width < this.position.x) ||
        (0 > this.position.y) ||
        (ctx.canvas.height < this.position.y)) {

        this.hitObstacle = true;
    }


        if (!this.hitObstacle && !this.hitTarget) {
            this.applyForce(this.dna.genes[this.geneCounter]);
            this.geneCounter = (this.geneCounter + 1) % this.dna.genes.length;
            this.update();
            // If I hit an edge or an obstacle
            this.obstacles(os);




        }
        // Draw me!
        if (!this.hitObstacle) {
            this.display(ctx);
        }
    }
    // Did I make it to the target?
    public checkTarget(ctx: CanvasRenderingContext2D) {
        let d = distanceEuclidean(
            this.position.x,
            this.position.y,
            0,
            this.target.position.x,
            this.target.position.y,
            0
        );
        if (d < this.recordDist) this.recordDist = d;

        if (this.target.contains(this.position) && !this.hitTarget) {

            this.hitTarget = true;

            // if ((0 > this.position.x) ||
            //     (ctx.canvas.width < this.position.x ) ||
            //     (0 > this.position.y) ||
            //     (ctx.canvas.height < this.position.y) ) {

            //     this.hitTarget = true;
            // }


        } else if (!this.hitTarget) {
            this.finishTime++;
        }
    }

    // Did I hit an obstacle?
    public obstacles(os: any) {
        for (let i = 0; i < os.length; i++) {
            let obs = os[i];
            if (obs.contains(this.position)) {
                this.hitObstacle = true;
            }
        }
    }
    public applyForce(f: any) {
        this.acceleration.add(f);
    }
    public update() {
        this.velocity.add(this.acceleration);
        this.position.add(this.velocity);
        this.acceleration.multi(0);
    }
    public display(ctx: CanvasRenderingContext2D) {

        // console.log(this.position);

        //   //background(255,0,0);
        //   let theta = this.velocity.heading() + Math.PI / 2;
        //   fill(200, 100);
        //   stroke(0);
        //   strokeWeight(1);
        //   push();
        //   translate(this.position.x, this.position.y);
        //   rotate(theta);

        //   // Thrusters
        //   rectMode(CENTER);
        //   fill(0);
        //   rect(-this.r / 2, this.r * 2, this.r / 2, this.r);
        //   rect(this.r / 2, this.r * 2, this.r / 2, this.r);

        //   // Rocket body
        //   fill(175);
        //   beginShape(TRIANGLES);
        //   vertex(0, -this.r * 2);
        //   vertex(-this.r, this.r * 2);
        //   vertex(this.r, this.r * 2);
        //   endShape();

        ctx.beginPath()
        ctx.arc(this.position.x, this.position.y, 10, 0, Math.PI * 2)
        ctx.closePath()
        ctx.fill();

        //   pop();
    }
    public getFitness() {
        return this.fitness;
    }
    public getDNA() {
        return this.dna;
    }
    public stopped() {
        return this.hitObstacle;
    }
}

class Obstacle {
    public position; w; h
    constructor(x: number, y: number, w: number, h: number) {
        this.position = new Vector3(x, y, 0);
        this.w = w;
        this.h = h;
    }
    public display(ctx: CanvasRenderingContext2D) {
        //   stroke(0);
        //   fill(175);
        //   strokeWeight(2);
        //   rectMode(CORNER);
        ctx.beginPath();
        ctx.rect(this.position.x, this.position.y, this.w, this.h);
        ctx.closePath()
        ctx.fill()
    }
    public contains(spot: any) {
        if (
            spot.x > this.position.x &&
            spot.x < this.position.x + this.w &&
            spot.y > this.position.y &&
            spot.y < this.position.y + this.h
        ) {
            return true;
        } else {
            return false;
        }
    }
}

// Smart Rockets
// The Nature of Code
// The Coding Train / Daniel Shiffman
// https://youtu.be/_of6UVV4HGo
// https://thecodingtrain.com/more/achive/nature-of-code/9-genetic-algorithms/9.5-fitness-genotype-vs-phenotype.html
// https://editor.p5js.org/codingtrain/sketches/BOTCxBDbO

// http://natureofcode.com

// Pathfinding w/ Genetic Algorithms

// A class to describe a population of "creatures"

// Initialize the population
class Population {
    mutationRate
    population
    matingPool: any
    generations
    target
    constructor(target: any, m: any, num: any) {
        this.target = target;
        this.mutationRate = m; // Mutation rate
        this.population = new Array(num); // Array to hold the current population
        this.matingPool = []; // ArrayList which we will use for our "mating pool"
        this.generations = 0; // Number of generations
        //make a new set of creatures
        for (let i = 0; i < this.population.length; i++) {
            let position = new Vector3(500 / 2, 500 + 20);
            this.population[i] = new Rocket(
                position, 
                this.target,
                new DNA(lifetime),
                this.population.length
            );
        }
    }
    public live(os: any, ctx: CanvasRenderingContext2D) {
        // For every creature
        for (let i = 0; i < this.population.length; i++) {
            // If it finishes, mark it down as done!
            this.population[i].checkTarget(ctx);
            this.population[i].run(os, ctx);
        }
    }
    // Did anything finish?
    public targetReached() {
        for (let i = 0; i < this.population.length; i++) {
            if (this.population[i].hitTarget) return true;
        }
        return false;
    }
    // Calculate fitness for each creature
    public calcFitness() {
        for (let i = 0; i < this.population.length; i++) {
            this.population[i].calcFitness();
        }
    }
    // Generate a mating pool
    public selection() {
        // Clear the ArrayList
        this.matingPool = [];

        // Calculate total fitness of whole population
        let maxFitness = this.getMaxFitness();

        // Calculate fitness for each member of the population (scaled to value between 0 and 1)
        // Based on fitness, each member will get added to the mating pool a certain number of times
        // A higher fitness = more entries to mating pool = more likely to be picked as a parent
        // A lower fitness = fewer entries to mating pool = less likely to be picked as a parent
        for (let i = 0; i < this.population.length; i++) {
            let fitnessNormal = remap(
                this.population[i].getFitness(),
                0,
                maxFitness,
                0,
                1
            );
            let n = Math.floor(fitnessNormal * 100); // Arbitrary multiplier
            for (let j = 0; j < n; j++) {
                this.matingPool.push(this.population[i]);
            }
        }
    }
    // Making the next generation
    public reproduction() {
        // Refill the population with children from the mating pool
        for (let i = 0; i < this.population.length; i++) {
            // Sping the wheel of fortune to pick two parents
            let m = Math.floor(Math.random() * (this.matingPool.length));
            let d = Math.floor(Math.random() * (this.matingPool.length));
            // Pick two parents
            let mom = this.matingPool[m];
            let dad = this.matingPool[d];
            // Get their genes
            let momgenes = mom.getDNA();
            let dadgenes = dad.getDNA();
            // Mate their genes
            let child = momgenes.crossover(dadgenes);
            // Mutate their genes
            child.mutate(this.mutationRate);
            // Fill the new population with the new child
            let position = new Vector3(500 / 2, 500 + 20);
            this.population[i] = new Rocket(position, this.target, child, this.population.length);
        }
        this.generations++;
    }
    public getGenerations() {
        return this.generations;
    }
    // Find highest fitness for the population
    public getMaxFitness() {
        let record = 0;
        for (let i = 0; i < this.population.length; i++) {
            if (this.population[i].getFitness() > record) {
                record = this.population[i].getFitness();
            }
        }
        return record;
    }
}
